#!/usr/bin/env node
/**
 * Static checks for the built plugin bundle. The build is generated by
 * build-library.ts, so regressions here (unscoped CSS, a lost font, a second
 * React copy, or a CDN reference) would otherwise only show up in a real GUI.
 */
import { readFile, readdir, stat } from 'node:fs/promises'
import { extname } from 'node:path'
import postcss from 'postcss'
import selectorParser from 'postcss-selector-parser'

const failures = []
const sizes = []

function fail(message) {
  failures.push(message)
}

function check(condition, message) {
  if (!condition) fail(message)
}

function kib(bytes) {
  return `${(bytes / 1024).toFixed(1)} KiB`
}

async function readText(path) {
  try {
    return await readFile(path, 'utf8')
  } catch {
    fail(`missing ${path}`)
    return ''
  }
}

async function sizeOf(path, min, max) {
  try {
    const info = await stat(path)
    sizes.push(`${path} ${kib(info.size)}`)
    check(info.size >= min, `${path} is unexpectedly small (${kib(info.size)} < ${kib(min)})`)
    check(info.size <= max, `${path} exceeds its budget (${kib(info.size)} > ${kib(max)})`)
    return info.size
  } catch {
    fail(`missing ${path}`)
    return 0
  }
}

await sizeOf('lib/host.js', 50 * 1024, 160 * 1024)
await sizeOf('lib/client.js', 40 * 1024, 120 * 1024)
await sizeOf('lib/assets/canvas.js', 10 * 1024 * 1024, 20 * 1024 * 1024)
await sizeOf('lib/assets/index.css', 100 * 1024, 300 * 1024)

const host = await readText('lib/host.js')
const client = await readText('lib/client.js')
const canvas = await readText('lib/assets/canvas.js')

check(host.includes('excalidraw_scene'), 'lib/host.js does not register the scene tool')
check(host.includes('userInvocable'), 'lib/host.js does not embed the user-invocable skill')
check(host.includes('api/excalidraw-assets/'), 'lib/host.js does not serve or reference the asset path')
check(client.includes('__ModuleLoader__.load'), 'lib/client.js is missing the DSH module loader wrapper')
check(client.includes('@zcong/dsh-excalidraw-plugin'), 'lib/client.js is missing the plugin id')
check(client.includes('api/excalidraw-assets/'), 'lib/client.js does not reference the Host asset path')
check(canvas.trimStart().startsWith('window.EXCALIDRAW_ASSET_PATH'), 'lib/assets/canvas.js does not set EXCALIDRAW_ASSET_PATH first')
check(canvas.includes('__DSH_EXCALIDRAW_SHARED__'), 'lib/assets/canvas.js does not use the shared React table')

for (const [name, text] of [['host', host], ['client', client], ['canvas', canvas]]) {
  check(!text.includes('sourceMappingURL'), `lib/${name} contains a source map reference`)
}
for (const cdn of ['cdn.jsdelivr.net', 'unpkg.com', 'cdnjs.cloudflare.com']) {
  check(!host.includes(cdn) && !client.includes(cdn), `the plugin bundle references ${cdn}`)
}
check(!client.includes('react-dom.production'), 'lib/client.js looks like it bundles a second React')

const manifestText = await readText('lib/assets/manifest.json')
let manifest
try {
  manifest = JSON.parse(manifestText)
} catch {
  fail('lib/assets/manifest.json is not valid JSON')
}
if (manifest !== undefined) {
  check(manifest.source === '@excalidraw/excalidraw@0.18.0', 'manifest source does not match the pinned Excalidraw version')
  check(manifest.assetPath === '/api/excalidraw-assets/', 'manifest assetPath is not the Host route')
  const fontFiles = (await readdir('lib/assets/fonts', { recursive: true })).filter((name) => name.endsWith('.woff2'))
  check(fontFiles.length >= 234, `only ${fontFiles.length} WOFF2 fonts were packaged`)
  check(fontFiles.length === manifest.fontFiles, 'manifest font count does not match the packaged fonts')
  check(manifest.families.includes('Xiaolai'), 'the Xiaolai CJK fallback font is missing')
}

const locales = await readdir('lib/assets/locales').catch(() => [])
check(locales.some((name) => /^zh-CN-.*\.js$/.test(name)), 'the zh-CN locale is missing')
check(locales.some((name) => /^en-.*\.js$/.test(name)), 'the en locale is missing')
check(locales.length >= 50, `only ${locales.length} locales were packaged`)

for (const path of ['lib/assets/LICENSE-excalidraw', 'lib/assets/THIRD_PARTY_NOTICES.md']) {
  const size = await stat(path).then((info) => info.size).catch(() => 0)
  check(size > 0, `${path} is missing or empty`)
}

const css = await readText('lib/assets/index.css')
let ruleCount = 0
try {
  const root = postcss.parse(css)
  root.walkRules((rule) => {
    const parent = rule.parent
    if (parent?.type === 'atrule' && /keyframes$/iu.test(parent.name)) return
    ruleCount += 1
    for (const selector of selectorParser().astSync(rule.selector).nodes) {
      const first = selector.first
      if (!(first?.type === 'class' && first.value === 'dsh-excalidraw-plugin')) {
        fail(`unscoped CSS selector: ${rule.selector.slice(0, 120)}`)
        return
      }
    }
  })
  root.walkAtRules((atRule) => {
    if (/^import$/iu.test(atRule.name) && /(?:https?:)?\/\//iu.test(atRule.params)) {
      fail(`remote CSS import: ${atRule.params}`)
    }
  })
  root.walkDecls((decl) => {
    for (const match of decl.value.matchAll(/url\(\s*(['"]?)([^'")]+)\1\s*\)/giu)) {
      const url = match[2].trim()
      if (/^(?:https?:)?\/\//iu.test(url)) fail(`remote CSS url in .${decl.prop}: ${url.slice(0, 100)}`)
    }
  })
  root.walkAtRules('font-face', (atRule) => {
    const source = atRule.nodes?.find((node) => node.type === 'decl' && node.prop === 'src')
    if (source === undefined) {
      fail('a @font-face rule has no src')
      return
    }
    for (const match of source.value.matchAll(/url\(\s*(['"]?)([^'")]+)\1\s*\)/giu)) {
      const url = match[2].trim()
      if (!url.startsWith('./fonts/')) fail(`font URL is not bundled: ${url.slice(0, 100)}`)
    }
  })
} catch (error) {
  fail(`lib/assets/index.css does not parse: ${error.message}`)
}
check(ruleCount > 100, `only ${ruleCount} scoped CSS rules were found`)

const maps = (await readdir('lib', { recursive: true })).filter((name) => extname(name) === '.map')
check(maps.length === 0, `lib contains source maps: ${maps.join(', ')}`)

if (failures.length > 0) {
  console.error(`build verification failed (${failures.length}):`)
  for (const failure of failures) console.error(`- ${failure}`)
  process.exit(1)
}
console.log(`build verification passed (${ruleCount} scoped CSS rules)`)
for (const size of sizes) console.log(`  ${size}`)
